package com.fintaxpro;
import java.nio.charset.StandardCharsets;import java.util.*;import javax.crypto.spec.SecretKeySpec;import com.nimbusds.jose.jwk.source.ImmutableSecret;import org.springframework.context.annotation.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.oauth2.jwt.*;import org.springframework.security.oauth2.jose.jws.MacAlgorithm;import org.springframework.security.web.SecurityFilterChain;import org.springframework.web.cors.*;
@Configuration public class SecurityConfig{
 @Bean PasswordEncoder passwords(){return new BCryptPasswordEncoder(12);}
 @Bean SecretKeySpec key(@Value("${fintax.jwt-secret}")String s){if(s.length()<32)throw new IllegalStateException("JWT_SECRET must contain at least 32 characters.");return new SecretKeySpec(s.getBytes(StandardCharsets.UTF_8),"HmacSHA256");}
 @Bean JwtEncoder encoder(SecretKeySpec k){return new NimbusJwtEncoder(new ImmutableSecret<>(k));}
 @Bean JwtDecoder decoder(SecretKeySpec k){NimbusJwtDecoder d=NimbusJwtDecoder.withSecretKey(k).macAlgorithm(MacAlgorithm.HS256).build();d.setJwtValidator(JwtValidators.createDefaultWithIssuer("fintaxpro"));return d;}
 @Bean SecurityFilterChain security(HttpSecurity http,@Value("${fintax.frontend-origin}")String origin)throws Exception{http.csrf(c->c.disable()).cors(c->c.configurationSource(req->{CorsConfiguration cfg=new CorsConfiguration();cfg.setAllowedOrigins(List.of(origin));cfg.setAllowedMethods(List.of("GET","POST","OPTIONS"));cfg.setAllowedHeaders(List.of("Content-Type","Authorization"));cfg.setAllowCredentials(true);return cfg;})).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/register","/api/auth/login","/api/auth/logout","/api/status").permitAll().anyRequest().authenticated()).oauth2ResourceServer(o->o.bearerTokenResolver(req->{String a=req.getHeader("Authorization");if(a!=null&&a.startsWith("Bearer "))return a.substring(7);if(req.getCookies()!=null)for(var c:req.getCookies())if(c.getName().equals("fintax_session"))return c.getValue();return null;}).jwt(j->{}));return http.build();}
}
